328	    final Configuration configuration = job.getConfiguration();
329	    Path targetPath = context.getTargetPath();
330	    FileSystem targetFS = targetPath.getFileSystem(configuration);
331	    targetPath = targetPath.makeQualified(targetFS.getUri(),
332	                                          targetFS.getWorkingDirectory());
333	    if (context.shouldPreserve(
334	        DistCpOptions.FileAttribute.ACL)) {
335	      DistCpUtils.checkFileSystemAclSupport(targetFS);
336	    }
337	    if (context.shouldPreserve(
338	        DistCpOptions.FileAttribute.XATTR)) {
339	      DistCpUtils.checkFileSystemXAttrSupport(targetFS);
340	    }
341	    if (context.shouldAtomicCommit()) {
342	      Path workDir = context.getAtomicWorkPath();
343	      if (workDir == null) {
344	        workDir = targetPath.getParent();
345	      }
346	      workDir = new Path(workDir, WIP_PREFIX + targetPath.getName()
347	                                + rand.nextInt());
348	      FileSystem workFS = workDir.getFileSystem(configuration);
349	      if (!FileUtil.compareFs(targetFS, workFS)) {
350	        throw new IllegalArgumentException("Work path " + workDir +
351	            " and target path " + targetPath + " are in different file system");
352	      }
353	      CopyOutputFormat.setWorkingDirectory(job, workDir);
354	    } else {
355	      CopyOutputFormat.setWorkingDirectory(job, targetPath);
356	    }
357	    CopyOutputFormat.setCommitDirectory(job, targetPath);
358	
359	    Path logPath = context.getLogPath();
360	    if (logPath == null) {
361	      logPath = new Path(metaFolder, "_logs");
362	    } else {
363	      LOG.info("DistCp job log path: " + logPath);
364	    }
365	    CopyOutputFormat.setOutputPath(job, logPath);
