293	+    Thread.sleep(500);
294	+    strTime = formatTimestamp(System.currentTimeMillis());
295	+    dateObj = parseTimestamp(strTime);
296	+
297	+    assertThat(shellRun("-touch", "-m", "-a", "-t", strTime, "dir2")).as(
298	+        "Expected successful touch with a specified modification time").isEqualTo(0);
299	+
300	+    newStatus = dfs.getFileStatus(dirPath);
