302	+    assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
303	+    assertThat(newStatus.getModificationTime()).isEqualTo(dateObj.getTime());
304	+
305	+    fileStatus = dfs.getFileStatus(dirPath);
306	+    Thread.sleep(500);
307	+
308	+    strTime = formatTimestamp(System.currentTimeMillis());
309	+    dateObj = parseTimestamp(strTime);
310	+
311	+    assertThat(shellRun("-touch", "-m", "-t", strTime, "dir2")).as(
312	+        "Expected successful touch with a specified modification time").isEqualTo(0);
313	+
314	+    newStatus = dfs.getFileStatus(dirPath);
315	+    // Verify if modification time is recorded correctly (and access time
316	+    // remains unchanged).
317	+    assertThat(newStatus.getAccessTime()).isEqualTo(fileStatus.getAccessTime());
318	+    assertThat(newStatus.getModificationTime()).isEqualTo(dateObj.getTime());
319	+
320	+    fileStatus = dfs.getFileStatus(dirPath);
321	+    Thread.sleep(500);
322	+
323	+    strTime = formatTimestamp(System.currentTimeMillis());
324	+    dateObj = parseTimestamp(strTime);
325	+
326	+    assertThat(shellRun("-touch", "-a", "-t", strTime, "dir2")).as(
327	+        "Expected successful touch with a specified modification time").isEqualTo(0);
328	+
329	+    newStatus = dfs.getFileStatus(dirPath);
330	+    // Verify if access time is recorded correctly (and modification time
331	+    // remains unchanged).
332	+    assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
333	+    assertThat(newStatus.getModificationTime()).isEqualTo(fileStatus.getModificationTime());
334	+
335	+    dfs.delete(newFile, true);
336	+    dfs.delete(dirPath, true);
